(() => {
  'use strict';

  // Paste/drop capture has no DOM-readiness dependency. Install it while
  // the document-start Tan source runs, before Discord's editor listeners.
  // The runtime owns these disposers even before its DOMContentLoaded start.
  const api = NokoTan;

  // NokoX 1.1.1
  // No network requests, Discord tokens, native bridge, or external helper.
  // It only rewrites URLs locally before Discord receives the pasted text.

  const TRACKING_PARAMS = new Set([
    's',
    't',
    'ref_src',
    'ref_url',
    'ref',
    'src'
  ]);

  function rewriteURL(raw) {
    let url;
    try {
      url = new URL(raw);
    } catch {
      return raw;
    }

    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    const isX = host === 'x.com' || host === 'mobile.x.com';
    const isTwitter = host === 'twitter.com' || host === 'mobile.twitter.com';

    if (!isX && !isTwitter) return raw;

    // Embed services are intended for actual posts, not arbitrary X pages.
    if (!/^\/[^/]+\/status\/\d+(?:\/|$)/i.test(url.pathname)) return raw;

    url.protocol = 'https:';
    url.hostname = isX ? 'fixupx.com' : 'fxtwitter.com';
    url.port = '';

    for (const key of [...url.searchParams.keys()]) {
      if (TRACKING_PARAMS.has(key.toLowerCase()) || key.toLowerCase().startsWith('utm_')) {
        url.searchParams.delete(key);
      }
    }

    return url.toString();
  }

  function rewriteText(text) {
    if (typeof text !== 'string' || !text) return text;

    // Stops at whitespace and common Discord/Markdown closing punctuation.
    return text.replace(
      /https?:\/\/(?:www\.)?(?:mobile\.)?(?:x\.com|twitter\.com)\/[^\s<>"'`]+/gi,
      match => {
        // Keep sentence punctuation outside the URL.
        const trailingMatch = match.match(/[),.!?;:]+$/);
        const trailing = trailingMatch ? trailingMatch[0] : '';
        const candidate = trailing ? match.slice(0, -trailing.length) : match;
        return rewriteURL(candidate) + trailing;
      }
    );
  }

  function composerFrom(node) {
    const element = node instanceof Element ? node : node?.parentElement;
    if (!element) return null;

    const editable = element.closest('[contenteditable="true"]');
    if (!editable) return null;

    // Discord's message composer is a Slate editor. The aria-label fallback
    // keeps this useful if Discord changes the Slate attribute later.
    if (editable.getAttribute('data-slate-editor') === 'true') return editable;
    const label = (editable.getAttribute('aria-label') || '').toLowerCase();
    return label.includes('message') ? editable : null;
  }

  function insertText(editable, text) {
    editable.focus();

    try {
      if (document.execCommand('insertText', false, text)) return true;
    } catch {}

    // Fallback for a future WebKit build where execCommand is unavailable.
    try {
      const selection = globalThis.getSelection?.();
      if (!selection || selection.rangeCount === 0) return false;
      const range = selection.getRangeAt(0);
      if (!editable.contains(range.commonAncestorContainer)) return false;

      range.deleteContents();
      const node = document.createTextNode(text);
      range.insertNode(node);
      range.setStartAfter(node);
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);

      editable.dispatchEvent(new InputEvent('input', {
        bubbles: true,
        inputType: 'insertText',
        data: text
      }));
      return true;
    } catch {
      return false;
    }
  }

  function onPaste(event) {
    const editable = composerFrom(event.target);
    if (!editable || !event.clipboardData || event.defaultPrevented) return;
    // Attachment-containing pastes belong to Discord/Nokonymise.
    if (event.clipboardData.files?.length) return;

    const original = event.clipboardData.getData('text/plain');
    if (!original) return;

    const rewritten = rewriteText(original);
    if (rewritten === original) return;

    event.preventDefault();
    event.stopPropagation();
    insertText(editable, rewritten);
  }

  // Dragging selected text/URLs into the composer should behave the same way.
  function onDrop(event) {
    const editable = composerFrom(event.target);
    if (!editable || !event.dataTransfer || event.defaultPrevented) return;
    if (event.dataTransfer.files?.length) return;

    const original = event.dataTransfer.getData('text/plain');
    if (!original) return;

    const rewritten = rewriteText(original);
    if (rewritten === original) return;

    event.preventDefault();
    event.stopPropagation();
    editable.focus();

    try {
      const caret = document.caretRangeFromPoint?.(event.clientX, event.clientY);
      if (caret) {
        const selection = globalThis.getSelection?.();
        selection?.removeAllRanges();
        selection?.addRange(caret);
      }
    } catch {}

    insertText(editable, rewritten);
  }

  api.listen(window, 'paste', onPaste, true);
  api.listen(window, 'drop', onDrop, true);

  // Expose a deliberately tiny diagnostics hook in this Tan's isolated world.
  // It contains no Discord/session data and disappears when the Tan stops.
  globalThis.NokoX = Object.freeze({
    rewrite: rewriteText,
    version: '1.1.1'
  });

  // Backward-compatible diagnostics alias for anyone testing the old name.
  globalThis.NokoLinkFixer = globalThis.NokoX;

  api.onCleanup(() => {
    try { delete globalThis.NokoX; } catch {}
    try { delete globalThis.NokoLinkFixer; } catch {}
  });
  // Register the normal lifecycle after the early hooks are owned. Startup
  // needs no further DOM work; disable/replacement still removes every hook.
  NokoTan.register({ start() {} });
})();
